Review this JavaScript code for security issues:

```javascript
const express = require('express');
const app = express();

let comments = [];

app.post('/comment', (req, res) => {
    comments.push({
        author: req.body.author,
        text: req.body.text,
        date: new Date()
    });
    res.redirect('/comments');
});

app.get('/comments', (req, res) => {
    let html = '<h1>Comments</h1>';
    comments.forEach(c => {
        html += `<div class='comment'>`;
        html += `<strong>${c.author}</strong>`;
        html += `<p>${c.text}</p>`;
        html += `</div>`;
    });
    res.send(html);
});
```

Language: JavaScript (Express.js)
Context: Blog comment system

